// === Tab: mySketch ===
// Blackout poetry
// For the #WCCChallenge << Obscure >> (join the discord! https://discord.gg/S8c7qcjw2b)
//
// For this sketch I wanted to work with text libraries, and the theme fit perfectly
// for a blackout poetry generator. I used the Gutenberg library to get some books,
// and the RiTa library (https://rednoise.org/rita/) to parse the text and get the
// parts of speech for each word. Then I used the parts of speech to find sequences
// within the text that match some predefined templates, find the words, then draw
// rectangles over the rest of the text.
// RiTa is limited to grammatical parts of speech, so the phrases usually don't
// make much sense, but it's still fun to play with, and you get surprised from
// time to time
// Possible future improvement: add a "manual" mode for you to select the words

// Controls:
// R: Pick up a new blackout phrase
// T: Pick up a new text
// + and -: Change the font size
// C: Toggle between blackout and clear mode (to see full text)
// F: Shuffle font family


let cw, ch, margin, fontSize
let texts, fonts, theFont
let selectedText, textAndTokens, blackoutPhrases, selectedBlackoutPhrase
let theSeed
let BG_COLOR = "#DDDDEE"
let texture
let mode = "blackout"

function preload() {
  let sources = [11, 16, 46, 1080, 1232, 1513, 1661, 5200].map((id) => `pg${id}.txt`)
  texts = []
  for (let i = 0; i < sources.length; i++) {
    loadStrings(sources[i], (text) => {
      texts[i] = parseGutenbergBook(text)
    })
  }
  fonts = []
  fontNames = ['CourierPrime-Regular.ttf', 'EBGaramond-VariableFont_wght.ttf', 'PTSans-Regular.ttf']
  for (let i = 0; i < fontNames.length; i++) {
    loadFont(fontNames[i], (font) => {
      fonts[i] = font
    })
  }
}

function setup() {
  let ar = 1 / 1.2 // Aspect ratio
  let windowAr = windowWidth / windowHeight
  let scaleRatio
  if (windowAr > ar) {
    ch = max(min(windowHeight, 1200), 600)
    cw = ch * ar
    scaleRatio = ch / 1200
  } else {
    cw = max(min(windowWidth, 1200), 600)
    ch = cw / ar
    scaleRatio = cw / 1000
  }
	pixelDensity(1)
  margin = cw * 0.1
  theFont = random(fonts)
  fontSize = 30

  createCanvas(cw, ch)
  if (scaleRatio !== 1) {
    scale(scaleRatio)
  }
  createPaperTexture()
  textFont(theFont)

  setupText()
  setupBlackout()
}

function draw() {
  background(BG_COLOR)
  image(texture, 0, 0, cw, ch)
  drawAuthorAndTitle()
  if (renderText()) {
    noLoop()
  }
}

// On press key: R picks up a new blackout phrase, T picks up a new text
// + and - change the font size, F to change font family
function keyPressed() {
  if (key === "r") {
    setupBlackout()
    loop()
  } else if (key === "t") {
    setupText()
    setupBlackout()
    loop()
  } else if (key === "+") {
    if (textSize() >= 60) return
    fontSize += 5
    setupText()
    setupBlackout()
    loop()
  } else if (key === "-") {
    if (textSize() <= 20) return
    fontSize -= 5
    setupText()
    setupBlackout()
    loop()
  } else if (key === "c") {
    mode = mode === "blackout" ? "clear" : "blackout"
    loop()
  } else if (key === "f") {
    theFont = random(fonts)
    textFont(theFont)
    setupText()
    setupBlackout()
    loop()
  }
}

let setupText = () => {
  selectedText = random(texts)

  textAndTokens = getTextSplitIntoTokens(
    selectedText.text,
    fontSize,
    margin,
    margin,
    cw - margin * 2,
    ch - margin * 2
  )

  // Get POS tags for each word, and add them to the object
  let words = textAndTokens.map((w) => w.token)
  let posTags = RiTa.pos(words)
  for (let i = 0; i < textAndTokens.length; i++) {
    textAndTokens[i].pos = posTags[i]
  }
}

let setupBlackout = () => {
  blackoutPhrases = getBlackoutWords(textAndTokens)
  selectedBlackoutPhrase = random(blackoutPhrases)
}

let renderText = () => {
  if (!textAndTokens) {
    return false // Not ready yet
  }
  let clearWordsIndices = selectedBlackoutPhrase.map((w) => {
    return textAndTokens.indexOf(w)
  })
  // Draw the text
  for (let i = 0; i < textAndTokens.length; i++) {
    let t = textAndTokens[i]
    fill(0)
    noStroke()
    text(t.token, t.x, t.y + t.ascent)
  }
  // Draw the blackout rectangles
  let rectangles = createRectangles(textAndTokens, clearWordsIndices)
  for (let r of rectangles) {
    if (mode === "blackout") {
      drawMarkerRect(r)
    } else {
      fill("#FFFF0020")
      rect(r.x, r.y, r.width, r.height)
    }
  }
  // Draw again the cleared text to remove the blackout rectangles over it
  for (let i = 0; i < textAndTokens.length; i++) {
    if (clearWordsIndices.includes(i)) {
      let t = textAndTokens[i]
      tint(255, 150)
      image(
        texture, t.x, t.y, t.width, textAscent() + textDescent(),
        t.x, t.y, t.width, textAscent() + textDescent()
      )

      fill(0)
      noStroke()
      text(t.token, t.x, t.y + t.ascent)
    }
  }

  return true
}

let drawMarkerRect = (rect) => {
  const numberOfParallelograms = floor(random(20, 40))
  const opacity = random(30, 50)
  const offsetRange = 5

  for (let i = 0; i < numberOfParallelograms; i++) {
    fill(0, 0, 0, opacity + random(-10, 10)) // Set color and opacity (RGBA)
    let offsetX = Math.random() * offsetRange - offsetRange / 2
    let offsetY = Math.random() * offsetRange - offsetRange / 2
    let sx = rect.x + random(-10, 10)
    let h = rect.height / random(1.5, 3)
    let sy = rect.y + random(rect.height - h)
    let offY = random(-5, 5)
    if (random() < 0.05) {
      offY = random(-25, 25)
    }

    quad(
      sx + offsetX,
      sy + offsetY - offY,
      sx + rect.width + offsetX,
      sy + offsetY + offY,
      sx + rect.width - offsetX,
      sy + h - offsetY + offY,
      sx - offsetX,
      sy + h - offsetY - offY
    )
  }
}

let createRectangles = (tokens, whitelistIndices) => {
  let rectangles = []
  let currentRect = null
  let lineHeight = textAscent() + textDescent()

  for (let i = 0; i < tokens.length; i++) {
    // Skip if the token is a new line
    if (tokens[i].token === "\n") continue
    // Check if the token is not in the whitelist
    if (!whitelistIndices.includes(i)) {
      if (currentRect === null) {
        // Start a new rectangle
        currentRect = {
          x: tokens[i].x,
          y: tokens[i].y,
          width: tokens[i].width,
          height: lineHeight,
        }
      } else {
        // Extend the current rectangle
        // Check for new line
        if (tokens[i].y !== currentRect.y) {
          // Finish the current rectangle and start a new one
          rectangles.push(currentRect)
          currentRect = {
            x: tokens[i].x,
            y: tokens[i].y,
            width: tokens[i].width,
            height: lineHeight,
          }
        } else {
          // Extend the rectangle width
          currentRect.width = tokens[i].x + tokens[i].width - currentRect.x
        }
      }
    } else if (currentRect !== null) {
      // Finish the current rectangle if it exists
      rectangles.push(currentRect)
      currentRect = null
    }
  }

  // Add the last rectangle if it exists
  if (currentRect !== null) {
    rectangles.push(currentRect)
  }

  return rectangles
}

let getTextSplitIntoTokens = (txt, fontSize, x, y, maxW, maxH) => {
  // Pick paragraphs and parse tokens, until they fit in the given space
  let initialX = x
  let currentX = x
  let currentY = y
  textSize(fontSize)

  let sw = textWidth(" ")

  let paragraphIndex = floor(random(txt.length))

  let tokenized = []
  maxH -= textAscent() // Remove the height from the baseline to the top of the text

  let _wG_1 = 0; while ((currentY < y + maxH) && ++_wG_1 < 20000) {
    let paragraph = txt[paragraphIndex % txt.length]
    paragraphIndex++
    let words = paragraph.split(" ")
    // If there are words that contain new lines, split each new line into its own token
    for (let w = 0; w < words.length; w++) {
      let word = words[w]
      let tokens = RiTa.tokenize(word)
      let wWidth = textWidth(word)
      if (currentX + wWidth > initialX + maxW) {
        currentX = initialX
        currentY += textLeading()
      }
      let charIndex = 0
      let tokenX = currentX

      // Break if currentY is over the limit
      if (currentY >= y + maxH) {
        break
      }

      for (let t of tokens) {
        tokenized.push({
          word: word,
          token: t,
          charIndex: charIndex,
          paragraphIndex: paragraphIndex,
          wordIndex: w,
          x: tokenX,
          y: currentY,
          ascent: textAscent(),
          width: textWidth(t),
        })
        charIndex += t.length
        tokenX = currentX + textWidth(word.substring(0, charIndex))
      }
      currentX += wWidth + sw
    }
    for (let i = 0; i < 2; i++) {
      let nextHeight = currentY + textLeading()
      if (nextHeight < y + maxH) {
        tokenized.push({
          word: "\n",
          token: "\n",
          charIndex: 0,
          paragraphIndex,
          wordIndex: words.length,
          x: initialX,
          y: currentY,
          width: 0,
          ascent: textAscent(),
        })
      }
      currentX = initialX
      currentY = nextHeight
    }
  }
  return tokenized
}

// Find all sequences of tokens in T that match the sequence of tokens in t
let findIndices = (T, t) => {
  let results = []
  let tLength = t.length
  let TLength = T.length

  for (let i = 0; i < TLength; i++) {
    if (T[i] === t[0]) {
      // Found the first token of t in T
      let indices = [i]
      let found = true

      for (let j = 1; j < tLength; j++) {
        let nextIndex = T.indexOf(t[j], indices[indices.length - 1] + 1)
        if (nextIndex !== -1) {
          indices.push(nextIndex)
        } else {
          // Token not found in sequence, break and mark as not found
          found = false
          break
        }
      }

      if (found) {
        results.push(indices)
      }
    }
  }

  if (results.length === 0) {
    // If no complete sequence is found, return -1 for each token in t
    return [new Array(tLength).fill(-1)]
  }

  return results
}

