let getBlackoutWords = (taggedWords) => {
  let keyPhrases = getKeyPhrases()

  let result = []
  for (let keyPhrase of keyPhrases) {
    let phrases = findIndices(
      taggedWords.map((w) => w.pos),
      keyPhrase
    )
    for (let phrase of phrases) {
      // Filter out phrases that don't have a match for one of the words
      phrase = phrase.filter((index) => index !== -1)
      let phraseText = phrase.map((index) => taggedWords[index])
      result.push(phraseText)
    }
  }
  // Remove empty phrases, and sort them by length
  result = result
    .filter((phrase) => phrase.length > 0)
    .sort((a, b) => b.length - a.length)
  return result
}

